namespace Payments;

public sealed class PaymentGateway
{
    private readonly HashSet<string> _chargedIds = [];
    private readonly HashSet<string> _refundedChargeIds = [];
    private int _counter;

    public Task<ChargeResult> ChargeAsync(string cardToken, decimal amount)
    {
        if (string.IsNullOrEmpty(cardToken))
            throw new ArgumentException("Card token is required.", nameof(cardToken));

        if (amount <= 0)
            throw new ArgumentException("Amount must be positive.", nameof(amount));

        if (cardToken == "tok_declined")
            return Task.FromResult(new ChargeResult($"ch_failed_{Interlocked.Increment(ref _counter)}", Success: false));

        var chargeId = $"ch_{Interlocked.Increment(ref _counter)}";
        _chargedIds.Add(chargeId);
        return Task.FromResult(new ChargeResult(chargeId, Success: true));
    }

    public Task<RefundResult> RefundAsync(string chargeId)
    {
        if (string.IsNullOrEmpty(chargeId))
            throw new ArgumentException("Charge ID is required.", nameof(chargeId));

        if (!_chargedIds.Contains(chargeId) || !_refundedChargeIds.Add(chargeId))
            return Task.FromResult(new RefundResult($"re_failed_{Interlocked.Increment(ref _counter)}", Success: false));

        var refundId = $"re_{Interlocked.Increment(ref _counter)}";
        return Task.FromResult(new RefundResult(refundId, Success: true));
    }
}

public record ChargeResult(string ChargeId, bool Success);
public record RefundResult(string RefundId, bool Success);

